enum Tree { Leaf(i32), Node { left: Box<Tree>, right: Box<Tree> } }
enum Path { Top, Left { right: Box<Tree>, up: Box<Path> }, Right { left: Box<Tree>, up: Box<Path> } }
struct Cursor { it: Box<Tree>, path: Box<Path> }        // the location
impl Cursor {
    fn up(self) -> Result<Self, Self> {                  // consume; rebuild the parent
        match *self.path {
            Path::Top => Err(self),
            Path::Left { right, up } => Ok(Self { it: Box::new(Tree::Node { left: self.it, right }), path: up }),
            Path::Right { left, up } => Ok(Self { it: Box::new(Tree::Node { left, right: self.it }), path: up }),
        }
    }
}

