use indextree::{Arena, NodeId};

let mut arena = Arena::new();
let root = arena.new_node("root");
let child = root.append_value("child", &mut arena);          // returns NodeId
let siblings: Vec<NodeId> = root.children(&arena).collect();
let parent: Option<NodeId> = child.ancestors(&arena).nth(1);  // walk up
let other = arena.new_node("other");
root.checked_append(other, &mut arena)?;                        // Result, not panic
